/**
 * Tiers for staged edits to files that also exist in the template upstream.
 * - allow: silently permitted (expected to differ per fork or regenerated by tooling)
 * - warn:  committed, with a non-blocking notice
 * - block: refused until the fork acknowledges the change
 * Rules are checked in order; the first match wins. Anything unmatched is `block`.
 */
export type UpstreamGuardTier = 'allow' | 'warn' | 'block';

const ALLOW_PATTERNS: readonly RegExp[] = [
  /(?:^|\/)convex\/_generated\//, // regenerated by hooks
  /(?:^|\/)package\.json$/, // forks tailor per-package scripts and dependencies
  /(?:^|\/)convex\/schema\.ts$/, // forks evolve their data model
  /(?:^|\/)(?:pnpm-lock\.yaml|package-lock\.json|yarn\.lock|bun\.lockb?)$/, // regenerated by installs
  /(?:^|\/)public\/.*\.(?:png|svg|ico|jpe?g|webp)$/, // branding assets every fork replaces
  /(?:^|\/)favicon\.ico$/, // app icon
  /(?:^|\/)services\/backend\/config\/featureFlags\.ts$/, // per-deployment feature flag values
];

const WARN_PATTERNS: readonly RegExp[] = [
  /\.mdx?$/i, // docs, memory, guides, AGENTS.md
  /(?:^|\/)\.(?:github|husky|vscode)\//, // CI, git hooks, editor settings
  /(?:^|\/)scripts\//, // repo tooling
  /(?:^|\/)[^/]*\.config\.[cm]?[jt]sx?$/, // eslint, lint-staged, next, vitest, etc.
  /(?:^|\/)(?:\.prettierrc|\.prettierignore|\.fallowrc\.jsonc|\.npmrc|\.gitignore)$/,
  /(?:^|\/)(?:turbo\.json|pnpm-workspace\.yaml)$/,
  /(?:^|\/)tsconfig[^/]*\.json$/,
  /(?:^|\/)\.fallow\/[^/]+\.json$/, // dead-code and duplication baselines suppress gates
  /\.css$/, // theme tokens a fork may restyle
  /(?:^|\/)components\.json$/, // shadcn/ui tooling config
  /(?:^|\/)services\/backend\/config\/[^/]+\.ts$/, // backend config modules, e.g. signupMethods.ts
];

export function classifyUpstreamFile(filePath: string): UpstreamGuardTier {
  if (ALLOW_PATTERNS.some((pattern) => pattern.test(filePath))) {
    return 'allow';
  }
  if (WARN_PATTERNS.some((pattern) => pattern.test(filePath))) {
    return 'warn';
  }
  return 'block';
}
